mapper.select:
SELECT d.type_id AS type, count(DISTINCT d.id) AS deposit_count, coalesce(sum(t.amount) FILTER ( WHERE t.direction = 'I' AND t.occurred_at >= #{fromTs} AND t.occurred_at < #{toTs}), 0) AS received, coalesce(sum(t.amount) FILTER ( WHERE t.direction = 'O' AND t.occurred_at >= #{fromTs} AND t.occurred_at < #{toTs}), 0) AS refunded, coalesce(sum(t.amount) FILTER ( WHERE t.direction = 'D' AND t.occurred_at >= #{fromTs} AND t.occurred_at < #{toTs}), 0) AS deducted, coalesce(sum(CASE t.direction WHEN 'I' THEN t.amount WHEN 'O' THEN -t.amount WHEN 'D' THEN -t.amount END) FILTER (WHERE t.occurred_at < #{toTs}), 0) AS balance FROM deposit d LEFT JOIN deposit_txn t ON t.deposit_id = d.id AND t.tenant_id = d.tenant_id
d.community_id = #{communityId}
GROUP BY d.type_id ORDER BY d.type_id

SELECT coalesce(sum(t.amount) FILTER (WHERE t.direction = 'I'), 0) AS received, coalesce(sum(t.amount) FILTER (WHERE t.direction = 'O'), 0) AS refunded, coalesce(sum(t.amount) FILTER (WHERE t.direction = 'D'), 0) AS deducted, (SELECT coalesce(sum(d.balance), 0) FROM deposit d
d.community_id = #{communityId}
) AS balance FROM deposit_txn t
EXISTS (SELECT 1 FROM deposit d2 WHERE d2.id = t.deposit_id AND d2.community_id = #{communityId})
